            {"id": "b1", "target": None, "base": None},
            {"id": "b1", "base": None, "target": None, "x": 1},
            {"id": 1, "base": None, "target": None},
            {"id": "", "base": None, "target": None},
        )
        for bad in bad_items:
            raw = json.dumps(
                {"ops": [{"op": "add", "id": "b1", "weight": 1},
